import React, { useEffect, useState } from "react";
import {
  Box,
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  IconButton,
  Button,
  Chip,
  Tooltip,
  Typography,
  TextField,
  InputAdornment,
  Skeleton,
} from "@mui/material";
import AddIcon from "@mui/icons-material/Add";
import EditIcon from "@mui/icons-material/Edit";
import DeleteIcon from "@mui/icons-material/Delete";
import ArticleIcon from "@mui/icons-material/Article";
import SearchIcon from "@mui/icons-material/Search";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import api from "../../api/axios";
import PageHeader from "../../components/PageHeader";

const fmt = (v) =>
  v != null
    ? `₹ ${Number(v).toLocaleString("en-IN", { minimumFractionDigits: 2 })}`
    : "—";

export default function CarPurchaseList() {
  const [purchases, setPurchases] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const navigate = useNavigate();

  const fetchAll = () => {
    setLoading(true);
    api
      .get("/car-purchases/get-all")
      .then((r) => {
        setPurchases(r.data.data || []);
        setFiltered(r.data.data || []);
      })
      .catch((e) => toast.error(e.message))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    fetchAll();
  }, []);

  useEffect(() => {
    const q = search.toLowerCase();
    setFiltered(
      purchases.filter(
        (p) =>
          p.numberPlate?.toLowerCase().includes(q) ||
          p.model?.toLowerCase().includes(q) ||
          p.purchasedByFirstname?.toLowerCase().includes(q),
      ),
    );
  }, [search, purchases]);

  const handleDelete = (id) => {
    if (!window.confirm("Delete this car purchase?")) return;
    api
      .delete(`/car-purchases/${id}`)
      .then(() => {
        toast.success("Deleted successfully");
        fetchAll();
      })
      .catch((e) => toast.error(e.message));
  };

  return (
    <Box>
      <PageHeader
        title="Car Purchases"
        action={
          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={() => navigate("/car-purchases/new")}
          >
            Add Purchase
          </Button>
        }
      />

      <Card>
        <CardContent sx={{ pb: "16px !important" }}>
          {/* Search */}
          <TextField
            placeholder="Search by plate, model or buyer..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            size="small"
            sx={{ mb: 2, width: 320 }}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon fontSize="small" color="action" />
                </InputAdornment>
              ),
            }}
          />

          <TableContainer
            component={Paper}
            elevation={0}
            sx={{ border: "1px solid #e0e0e0", borderRadius: 2 }}
          >
            <Table size="small">
              <TableHead>
                <TableRow>
                  {[
                    "#",
                    "Number Plate",
                    "Model",
                    "Purchase Amt",
                    "Sale Amt",
                    "Purchase Date",
                    "Purchased By",
                    "Status",
                    "Actions",
                  ].map((h) => (
                    <TableCell key={h}>{h}</TableCell>
                  ))}
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  [...Array(5)].map((_, i) => (
                    <TableRow key={i}>
                      {[...Array(9)].map((_, j) => (
                        <TableCell key={j}>
                          <Skeleton />
                        </TableCell>
                      ))}
                    </TableRow>
                  ))
                ) : filtered.length === 0 ? (
                  <TableRow>
                    <TableCell
                      colSpan={9}
                      align="center"
                      sx={{ py: 5, color: "text.secondary" }}
                    >
                      No records found
                    </TableCell>
                  </TableRow>
                ) : (
                  filtered.map((p, idx) => (
                    <TableRow key={p.id} hover>
                      <TableCell>{idx + 1}</TableCell>
                      <TableCell>
                        <Typography
                          fontWeight={600}
                          color="primary.main"
                          fontSize="0.85rem"
                        >
                          {p.numberPlate}
                        </Typography>
                      </TableCell>
                      <TableCell>{p.model}</TableCell>
                      <TableCell>{fmt(p.purchaseAmount)}</TableCell>
                      <TableCell>
                        {p.saledAmount ? fmt(p.saledAmount) : "—"}
                      </TableCell>
                      <TableCell>{p.purchaseDate}</TableCell>
                      <TableCell>{p.purchasedByFirstname}</TableCell>
                      <TableCell>
                        <Chip
                          label={p.saledAmount ? "Sold" : "Available"}
                          size="small"
                          color={p.saledAmount ? "success" : "warning"}
                          sx={{ fontSize: "0.68rem" }}
                        />
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: "flex", gap: 0.5 }}>
                          <Tooltip title="Edit">
                            <IconButton
                              size="small"
                              color="primary"
                              onClick={() =>
                                navigate(`/car-purchases/edit/${p.id}`)
                              }
                            >
                              <EditIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                          <Tooltip title="Delete">
                            <IconButton
                              size="small"
                              color="error"
                              onClick={() => handleDelete(p.id)}
                            >
                              <DeleteIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                          <Tooltip title="Invoice">
                            <IconButton
                              size="small"
                              sx={{ color: "#1b5e20" }}
                              onClick={() => navigate(`/invoice?carId=${p.id}`)}
                            >
                              <ArticleIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          </TableContainer>

          <Typography
            variant="caption"
            color="text.secondary"
            sx={{ mt: 1, display: "block" }}
          >
            Showing {filtered.length} of {purchases.length} records
          </Typography>
        </CardContent>
      </Card>
    </Box>
  );
}
